input.command:
cd /tmp/rv; ROW=/workspace/pr/head/evals/harness/ablation-row.sh; good="$(grep -m1 '"task_type": "review-catch"' fx/main/runs.jsonl)"; 
for f in '.defects_missed = "d2"' '.defects_missed = ["d2", 3]' '.defects_missed = [""]' '.defects_missed = [["d2"]]' '.regressions_final_green = "yes"' '.regressions_final_green = 1' '.defects_missed = null | .regressions_final_green = true' '.defects_missed = ["d2","d5"] | .regressions_final_green = false' 'del(.defects_missed) | del(.regressions_final_green)'; do jq -c "$f" <<<"$good" > one.jsonl; printf '%-60s -> ' "$f"; bash $ROW --validate one.jsonl 2>&1 | tail -1 | cut -c1-140; done
echo "== base bats fixture names / regressions shape"; grep -n 'a3-review\|a1-build\|a5-build\|a1-review' /workspace/pr/base/evals/tests/ablation-row.bats | head -8; grep -n 'regressions' /workspace/pr/base/evals/tests/ablation-row.bats | head -8; sed -n '1,40p' /workspace/pr/head/evals/tests/ablation-row.bats
